fn quadratic_big(x: &BigUint, c: &BigUint, n: &BigUint) -> BigUint {
    let x2 = (x * x) % n;
    (&x2 + c) % n
}

fn big_gcd(mut a: BigUint, mut b: BigUint) -> BigUint {
    while !b.is_zero() {
        let t = b.clone();
        b = &a % &b;
        a = t;
    }
    a
