  1	//! Grammar-native representation of functional-graph dynamics.
  2	//!
  3	//! `cycle`, `combo2` and every rotation-orbit reading in this codebase read
  4	//! one specific kind of orbit: a word's own, where ROTAT is a bijection and
  5	//! every element therefore has tail length zero -- the graph is a disjoint
  6	//! union of pure cycles, nothing feeding in from outside. An arbitrary map
  7	//! f: S -> S need not be injective or surjective, so most elements have more
  8	//! than one predecessor and some have none; iterating from any element walks
  9	//! a rho-shaped path, a tail of unique length ending on a cycle. That
 10	//! asymmetry between forward step and backward step is the actual content
 11	//! here, and no existing instrument in this project reads it, because all of
 12	//! them assume invertibility. See ig-docs/functional_graph_reference.md,
 13	//! whose spec this implements.
 14	//!
 15	//! Two algorithms, both textbook, both here so the constant-memory one
 16	//! (Brent) can be checked against the two-pointer baseline (Floyd) on the
 17	//! same map before either is trusted. `floyd`/`brent`/`decompose` are the
 18	//! general form, any f: u64 -> u64, over a domain small enough to walk in
 19	//! full; `decompose` is the third capability neither point-reading gives,
 20	//! walking the WHOLE finite domain once and returning every rho-component,
 21	//! not just the one reached from a chosen start.
 22	//!
 23	//! `pollard_rho_brent` is the same rho-shaped-orbit phenomenon at a
 24	//! different scale: `prime_winding.rs` and `dynamic_nesting_prime_finder.rs`
 25	//! each used to carry their own private copy of Brent's-variant walk over
 26	//! BigUint, hardwired to x^2+c mod N for factoring. Same algorithm, same
 27	//! external (non-Grammar-native) technique reached for twice independently
 28	//! instead of once, from here. Both now call the one copy below.
 29	
 30	use alloc::string::{String, ToString};
 31	use alloc::vec::Vec;
 32	use alloc::vec;
 33	use alloc::format;
 34	use num_bigint::BigUint;
 35	use num_traits::{One, Zero};
 36	
 37	/// Floyd's tortoise-and-hare: the two-pointer baseline. Returns
 38	/// (tail_length, cycle_length) = (mu, lambda) for the orbit of x0 under f.
 39	/// O(mu + lambda) steps, two pointers of state.
 40	pub fn floyd<F: Fn(u64) -> u64>(f: F, x0: u64) -> (u64, u64) {
 41	    let mut tortoise = f(x0);
 42	    let mut hare = f(f(x0));
 43	    while tortoise != hare {
 44	        tortoise = f(tortoise);
 45	        hare = f(f(hare));
 46	    }
 47	
 48	    // tortoise now sits at some point on the cycle; find where the tail
 49	    // from x0 first touches it by walking both from a common distance.
 50	    let mut mu = 0u64;
 51	    let mut tortoise = x0;
 52	    while tortoise != hare {
 53	        tortoise = f(tortoise);
 54	        hare = f(hare);
 55	        mu += 1;
 56	    }
 57	
 58	    let mut lambda = 1u64;
 59	    let mut hare = f(tortoise);
 60	    while tortoise != hare {
 61	        hare = f(hare);
 62	        lambda += 1;
 63	    }
 64	
 65	    (mu, lambda)
 66	}
 67	
 68	/// Brent's variant: power-of-two bursts against a fixed checkpoint reset at
 69	/// the start of each burst, per ig-docs/functional_graph_reference.md.
 70	/// Same (tail_length, cycle_length) answer as `floyd`, same asymptotic step
 71	/// count, fewer function evaluations in practice since it never re-walks
 72	/// the tortoise every step during cycle-length discovery.
 73	pub fn brent<F: Fn(u64) -> u64>(f: F, x0: u64) -> (u64, u64) {
 74	    let mut power = 1u64;
 75	    let mut lambda = 1u64;
 76	    let mut tortoise = x0;
 77	    let mut hare = f(x0);
 78	    while tortoise != hare {
 79	        if power == lambda {
 80	            tortoise = hare;
 81	            power *= 2;
 82	            lambda = 0;
 83	        }
 84	        hare = f(hare);
 85	        lambda += 1;
 86	    }
 87	
 88	    // mu: walk a hare lambda steps ahead of x0, then close the gap in lockstep.
 89	    let mut tortoise = x0;
 90	    let mut hare = x0;
 91	    for _ in 0..lambda {
 92	        hare = f(hare);
 93	    }
 94	    let mut mu = 0u64;
 95	    while tortoise != hare {
 96	        tortoise = f(tortoise);
 97	        hare = f(hare);
 98	        mu += 1;
 99	    }
100	
101	    (mu, lambda)
102	}
103	
104	/// One rho-shaped component: a cycle, and every tail vertex that feeds into
105	/// it paired with its exact distance to the cycle.
106	pub struct RhoComponent {
107	    pub cycle: Vec<u64>,
108	    pub tails: Vec<(u64, u64)>, // (vertex, tail_length), tail_length >= 1
109	}
110	
111	/// The full functional graph of f restricted to {0, ..., domain-1} (f's
112	/// output is taken mod domain, so f always stays inside the set). One pass,
113	/// O(domain) total work: walk each unvisited vertex's path, colour it
114	/// in-progress, and stop either at a vertex already in-progress (a new
115	/// cycle, found where the path first revisits itself) or at a vertex
116	/// already finished (this path's tail lands on an already-known component).
117	pub fn decompose<F: Fn(u64) -> u64>(f: F, domain: u64) -> Vec<RhoComponent> {
118	    const UNVISITED: u8 = 0;
119	    const IN_PROGRESS: u8 = 1;
120	    const DONE: u8 = 2;
121	
122	    let n = domain as usize;
123	    let mut state = vec![UNVISITED; n];
124	    let mut tail_len = vec![0u64; n];
125	    let mut component_of = vec![usize::MAX; n];
126	    let mut components: Vec<RhoComponent> = Vec::new();
127	
128	    for start in 0..n as u64 {
129	        if state[start as usize] != UNVISITED {
130	            continue;
131	        }
132	        let mut path: Vec<u64> = Vec::new();
133	        let mut x = start;
134	        while state[x as usize] == UNVISITED {
135	            state[x as usize] = IN_PROGRESS;
136	            path.push(x);
137	            x = f(x) % domain;
138	        }
139	
140	        if state[x as usize] == IN_PROGRESS {
141	            // x sits on this very path: the path from its first occurrence
142	            // to the end is the new cycle.
143	            let idx = path.iter().position(|&v| v == x).unwrap();
144	            let cycle: Vec<u64> = path[idx..].to_vec();
145	            let cid = components.len();
146	            for &v in &cycle {
147	                component_of[v as usize] = cid;
148	                tail_len[v as usize] = 0;
149	            }
150	            for (i, &v) in path[..idx].iter().enumerate() {
151	                let dist = (idx - i) as u64;
152	                tail_len[v as usize] = dist;
153	                component_of[v as usize] = cid;
154	            }
155	            components.push(RhoComponent { cycle, tails: Vec::new() });
156	        } else {
157	            // x is DONE: this whole path is tail feeding into its component.
158	            let cid = component_of[x as usize];
159	            let base = tail_len[x as usize];
160	            for (i, &v) in path.iter().enumerate().rev() {
161	                let dist = base + (path.len() - i) as u64;
162	                tail_len[v as usize] = dist;
163	                component_of[v as usize] = cid;
164	            }
165	        }
166	
167	        for &v in &path {
168	            state[v as usize] = DONE;
169	        }
170	    }
171	
172	    for v in 0..n as u64 {
173	        let dist = tail_len[v as usize];
174	        if dist > 0 {
175	            let cid = component_of[v as usize];
176	            components[cid].tails.push((v, dist));
177	        }
178	    }
179	
180	    components
181	}
182	
183	/// The doc's own contrast, made checkable: a bijection's functional graph
184	/// has tail length zero everywhere. True iff every vertex sits directly on
185	/// a cycle -- iff `decompose` found no tails at all.
186	pub fn is_bijection_on<F: Fn(u64) -> u64>(f: F, domain: u64) -> bool {
187	    decompose(f, domain).iter().all(|c| c.tails.is_empty())
188	}
