190	fn quadratic(n: u64, c: u64) -> impl Fn(u64) -> u64 {
191	    move |x| {
192	        let x = x as u128;
193	        let c = c as u128;
194	        let n = n as u128;
195	        ((x * x + c) % n) as u64
196	    }
197	}
