213	/// Brent's power-of-two-burst rho walk, gcd-driven: the same rho-shaped
214	/// orbit `decompose` reads directly on a small domain, applied where the
215	/// domain itself (mod n) is too large to walk in full. The collision this
216	/// finds is not "tortoise meets hare on the same orbit mod n" -- that would
217	/// need on the order of sqrt(n) steps by brute force -- it is a collision
218	/// mod some unknown, much smaller prime factor p of n, surfaced the moment
219	/// it happens via gcd(|hare - tortoise|, n), in around sqrt(p) steps,
220	/// without n's factors ever being known in advance. This is the standard
221	/// application ig-docs/functional_graph_reference.md's own closing
222	/// paragraph names.
223	///
224	/// x is the tortoise, fixed for the whole doubling round r; y is the hare,
225	/// walked r steps ahead of x and compared against it in batches of `batch`,
226	/// accumulating the product of differences mod n so one gcd covers the
227	/// whole batch (`batch = 1` checks every single step instead, more gcd
228	/// calls, no batching at all). A batch gcd landing on n itself -- more than
229	/// one collision folded into the same batch -- is recovered by re-walking
230	/// that batch from its own start (`ys`), one step at a time, until the
231	/// exact collision point splits out the real factor. Returns a nontrivial
232	/// factor of n if the walk crosses one within max_power doubling rounds,
233	/// None otherwise -- Brent's rho carries no guaranteed termination on a
234	/// genuinely hard composite, and that is this walk's real, known shape,
235	/// not a defect to hide.
236	pub fn pollard_rho_brent(n: &BigUint, c: &BigUint, x0: &BigUint, batch: u64, max_power: u64) -> Option<BigUint> {
237	    let one = BigUint::one();
238	    let mut x = x0.clone();
239	    let mut y = x.clone();
240	    let mut r: u64 = 1;
241	    let mut g = one.clone();
242	    let mut q = one.clone();
243	    let mut ys = y.clone();
244	
245	    while g.is_one() && r < max_power {
246	        x = y.clone();
247	        for _ in 0..r {
248	            y = quadratic_big(&y, c, n);
249	        }
250	        let mut k: u64 = 0;
251	        while k < r && g.is_one() {
252	            ys = y.clone();
253	            let steps = batch.min(r - k);
254	            for _ in 0..steps {
255	                y = quadratic_big(&y, c, n);
256	                let diff = if y > x { &y - &x } else { &x - &y };
257	                q = (&q * diff) % n;
258	            }
259	            g = big_gcd(q.clone(), n.clone());
260	            k += batch;
261	        }
262	        r = match r.checked_mul(2) { Some(v) => v, None => break };
263	    }
264	
265	    if &g == n {
266	        loop {
267	            ys = quadratic_big(&ys, c, n);
268	            let diff = if ys > x { &ys - &x } else { &x - &ys };
269	            g = big_gcd(diff, n.clone());
270	            if !g.is_one() { break; }
271	        }
272	    }
273	
274	    if !g.is_one() && &g != n { Some(g) } else { None }
275	}
