288	    let c: u64 = match c_str.parse() { Ok(v) => v, _ => return "fgraph point: c must be a non-negative integer".to_string() };
289	    let x0: u64 = match x0_str.parse::<u64>() { Ok(v) => v % n, _ => return "fgraph point: x0 must be a non-negative integer".to_string() };
290	
291	    let f = quadratic(n, c);
292	    let (mu_f, lam_f) = floyd(&f, x0);
293	    let (mu_b, lam_b) = brent(&f, x0);
294	
295	    let mut out = String::new();
296	    out.push_str(&format!("f(x) = x^2 + {} mod {}, x0 = {}\n", c, n, x0));
297	    out.push_str(&format!("  Floyd : tail = {}, cycle = {}\n", mu_f, lam_f));
298	    out.push_str(&format!("  Brent : tail = {}, cycle = {}\n", mu_b, lam_b));
299	    if mu_f == mu_b && lam_f == lam_b {
