314	    let mut out = String::new();
315	    out.push_str(&format!("f(x) = x^2 + {} mod {}: {} rho-component(s)\n", c, n, components.len()));
316	    let mut total_tail = 0u64;
317	    let mut max_tail = 0u64;
318	    for (i, comp) in components.iter().enumerate() {
319	        out.push_str(&format!(
320	            "  component {}: cycle length {} ({:?}), {} tail vertice(s)\n",
321	            i, comp.cycle.len(), comp.cycle, comp.tails.len()
322	        ));
