280	    out.push_str("  fgraph point <n> <c> <x0>      tail/cycle length of x0 under x -> x^2+c mod n, Floyd and Brent cross-checked\n");
281	    out.push_str("  fgraph decompose <n> <c>       the whole functional graph on {0..n-1} under x -> x^2+c mod n: every rho-component\n");
282	    out.push_str("  fgraph bijection <n> <k>       control: x -> x+k mod n is a bijection -- verifies every tail length is zero\n");
